const subjects = ['Quick question', 'Following up', 'Re: our chat', 'Idea for next week', 'Checking in'];
const bodies = ['Hey — just wanted to follow up on this. Talk soon.', 'Thanks again, let me know your thoughts.', 'Circling back on this one when you have a moment.', 'Hope your week is going well!'];
const recips = ($env.WARMUP_RECIPIENTS || '').split(',').map(s => s.trim()).filter(Boolean);
const to = recips[Math.floor(Math.random()*recips.length)] || '';
return [{ json: { to, subject: subjects[Math.floor(Math.random()*subjects.length)], body: bodies[Math.floor(Math.random()*bodies.length)] } }];
